import { USERS, PASSWORD, expect, expectStatus, test } from "../../fixtures";

test.describe("LIF-12 vendor lifecycle", () => {
  test("an admin can review vendors", { tag: "@LIF-12" }, async ({ apiAs, factory }) => {
    // Arrange: an admin session and a vendor in review with three pending extractions
    const admin = await apiAs("admin");
    const vendor = await factory.vendorInReview({ name: `LIF-12 Review ${Date.now()}` });

    // Act: open the review queue and approve the vendor's "w9" extraction
    const queueResponse = await admin.get("/api/review-queue");
    const queue = await expectStatus<Array<{ vendor_id: string; extractions: Array<{ id: string; kind: string }> }>>(queueResponse, 200);

    const entry = queue.find((item) => item.vendor_id === vendor.id);
    expect(entry, "vendor should be listed in the review queue").toBeDefined();

    const w9 = entry!.extractions.find((e) => e.kind === "w9");
    expect(w9, "vendor should have a w9 extraction").toBeDefined();

    const decisionResponse = await admin.post(`/api/extractions/${w9!.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert: the decision succeeds and the queue lists the vendor
    await expectStatus(decisionResponse, 200);

    const queueAfter = await expectStatus<Array<{ vendor_id: string }>>(await admin.get("/api/review-queue"), 200);
    expect(queueAfter.some((item) => item.vendor_id === vendor.id)).toBe(true);
  });
});
